const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brazil = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Brazil'))
    .geometry();

  const date2007 = {start: '2007-01-01', end: '2007-12-31'};
  const date2019 = {start: '2019-01-01', end: '2019-12-31'};

  // 2. Data Acquisition & Check
  const fireCol2007 = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(date2007.start, date2007.end)
    .filterBounds(brazil);

  const fireCol2019 = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(date2019.start, date2019.end)
    .filterBounds(brazil);

  const size2007 = fireCol2007.size().getInfo();
  const size2019 = fireCol2019.size().getInfo();

  console.log(`2007 Images: ${size2007}`);
  console.log(`2019 Images: ${size2019}`);

  if (size2007 === 0 || size2019 === 0) {
    console.log("Missing data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  // FireMask band: 0-8 are valid fire classes, 9 is no fire
  // We'll count pixels where FireMask is between 0 and 8
  const countFires = function(collection) {
    return collection.map(function(img) {
      const fireMask = img.select('FireMask').lte(8);
      return img.updateMask(fireMask);
    }).select('FireMask').sum();
  };

  const fires2007 = countFires(fireCol2007);
  const fires2019 = countFires(fireCol2019);

  // 4. Calculation
  const count2007 = fires2007.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: brazil,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  const count2019 = fires2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: brazil,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`2007 Fire Detections: ${count2007}`);
  console.log(`2019 Fire Detections: ${count2019}`);

  // 5. Validation & Final Answer
  if (count2007 === null || count2019 === null) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (count2007 === 0 && count2019 === 0) {
    console.log("No valid fire pixels detected in either year.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (count2019 < count2007) {
    console.log("Fewer fires in 2019 than 2007.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Equal or more fires in 2019 than 2007.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
